import{_ as i,o as a,c as s,a2 as t}from"./chunks/framework.BXzK3EA4.js";const o="/depends_vs_rdepends.png",k=JSON.parse('{"title":"Day 13: Recipe Dependencies (DEPENDS & RDEPENDS)","description":"","frontmatter":{},"headers":[],"relativePath":"day13-recipe-dependencies-depends-rdepends.md","filePath":"day13-recipe-dependencies-depends-rdepends.md"}'),d={name:"day13-recipe-dependencies-depends-rdepends.md"};function n(l,e,r,p,c,h){return a(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="day-13-recipe-dependencies-depends-rdepends" tabindex="-1">Day 13: Recipe Dependencies (DEPENDS &amp; RDEPENDS) <a class="header-anchor" href="#day-13-recipe-dependencies-depends-rdepends" aria-label="Permalink to &quot;Day 13: Recipe Dependencies (DEPENDS &amp; RDEPENDS)&quot;">​</a></h1><div style="background:linear-gradient(135deg, #11998e 0%, #38ef7d 100%);padding:1.5rem;border-radius:12px;margin-bottom:2rem;color:white;"><p><strong>🎯 Learning Objectives</strong></p><p>By the end of this module, you will be able to:</p><ol><li>Distinguish between build-time (<code>DEPENDS</code>) and run-time (<code>RDEPENDS</code>) dependencies</li><li>Understand how BitBake constructs the <code>recipe-sysroot</code> sandbox</li><li>Use <code>bitbake -g</code> to generate and analyze dependency graphs</li><li>Resolve &quot;missing header&quot; and &quot;command not found&quot; errors</li></ol></div><div class="info custom-block"><p class="custom-block-title">PREREQUISITES</p><ul><li>Completed <a href="/day12-static-and-dynamic-shared-libraries.html">Day 12: Static &amp; Dynamic Shared Libraries</a></li></ul></div><hr><h2 id="_1-the-two-types-of-dependencies" tabindex="-1">1. The Two Types of Dependencies <a class="header-anchor" href="#_1-the-two-types-of-dependencies" aria-label="Permalink to &quot;1. The Two Types of Dependencies&quot;">​</a></h2><p>In a massive build system like Yocto with thousands of interconnected recipes, BitBake must know exactly what order to build things in. If Recipe A requires a library provided by Recipe B, BitBake must build Recipe B first.</p><p>There are two fundamentally different types of dependencies in Yocto:</p><p><img src="'+o+'" alt="DEPENDS vs RDEPENDS"></p><h3 id="build-time-dependencies-depends" tabindex="-1">Build-Time Dependencies (<code>DEPENDS</code>) <a class="header-anchor" href="#build-time-dependencies-depends" aria-label="Permalink to &quot;Build-Time Dependencies (`DEPENDS`)&quot;">​</a></h3><p>If your C code <code>#include &lt;png.h&gt;</code>, your recipe cannot compile until the <code>libpng</code> recipe has been built and its headers made available to the cross-compiler.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># This forces BitBake to build &#39;libpng&#39; and &#39;zlib&#39; BEFORE compiling this recipe.</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">DEPENDS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;libpng zlib&quot;</span></span></code></pre></div><h3 id="run-time-dependencies-rdepends" tabindex="-1">Run-Time Dependencies (<code>RDEPENDS</code>) <a class="header-anchor" href="#run-time-dependencies-rdepends" aria-label="Permalink to &quot;Run-Time Dependencies (`RDEPENDS`)&quot;">​</a></h3><p>If your application is a bash script that calls <code>curl</code>, it doesn&#39;t need <code>curl</code> to &quot;compile&quot; (it&#39;s just a text file). However, if <code>curl</code> isn&#39;t installed on the final target board, your script will crash at runtime.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># This tells BitBake: &quot;If this package is installed on the image, make sure bash and curl are installed too.&quot;</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Notice the syntax requires appending the package name (${PN})</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">RDEPENDS:$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">{PN}</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;bash curl&quot;</span></span></code></pre></div><hr><h2 id="_2-the-sandbox-recipe-sysroot" tabindex="-1">2. The Sandbox: <code>recipe-sysroot</code> <a class="header-anchor" href="#_2-the-sandbox-recipe-sysroot" aria-label="Permalink to &quot;2. The Sandbox: `recipe-sysroot`&quot;">​</a></h2><p>To ensure reproducible builds, BitBake executes every recipe in an isolated sandbox.</p><p>When your recipe runs <code>do_compile</code>, the cross-compiler does <strong>not</strong> look in your host machine&#39;s <code>/usr/include</code> for headers. It looks in a temporary, highly-controlled folder called <code>recipe-sysroot</code>.</p><h3 id="how-depends-populates-the-sysroot" tabindex="-1">How <code>DEPENDS</code> Populates the Sysroot <a class="header-anchor" href="#how-depends-populates-the-sysroot" aria-label="Permalink to &quot;How `DEPENDS` Populates the Sysroot&quot;">​</a></h3><p>When you set <code>DEPENDS = &quot;libpng&quot;</code>, BitBake performs a specialized task called <code>do_prepare_recipe_sysroot</code> just before compilation.</p><ol><li>It finds the outputs of the <code>libpng</code> recipe.</li><li>It physically copies <code>png.h</code> and <code>libpng.so</code> into your recipe&#39;s private <code>recipe-sysroot/usr/include</code> and <code>recipe-sysroot/usr/lib</code>.</li><li>It configures the cross-compiler to only search inside <code>recipe-sysroot</code>.</li></ol><p>If you forget to declare <code>DEPENDS = &quot;libpng&quot;</code>, the compiler will fail with <code>fatal error: png.h: No such file or directory</code>, <em>even if <code>libpng</code> was built previously by another recipe</em>.</p><hr><h2 id="_3-dependency-graphs" tabindex="-1">3. Dependency Graphs <a class="header-anchor" href="#_3-dependency-graphs" aria-label="Permalink to &quot;3. Dependency Graphs&quot;">​</a></h2><p>Sometimes, you end up with a massive image and you want to know <em>why</em> a specific package is being installed.</p><p>BitBake can generate a DOT-formatted graph of every dependency required to build an image.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Generate task-depends.dot and package-depends.dot</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bitbake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> core-image-minimal</span></span></code></pre></div><h3 id="analyzing-the-graph" tabindex="-1">Analyzing the Graph <a class="header-anchor" href="#analyzing-the-graph" aria-label="Permalink to &quot;Analyzing the Graph&quot;">​</a></h3><p>You can use standard Linux tools to analyze the <code>.dot</code> file.</p><p>To convert the graph to a visual PDF (Warning: It will be massive and hard to read):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> graphviz</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dot</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Tpdf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> task-depends.dot</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dependencies.pdf</span></span></code></pre></div><p>To find out exactly what pulled <code>python3</code> into your image using <code>grep</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;-&gt; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> task-depends.dot</span></span></code></pre></div><p><em>(This shows every package that has an arrow pointing to python3)</em></p><hr><h2 id="_4-hands-on-lab-exercises" tabindex="-1">4. Hands-On Lab Exercises <a class="header-anchor" href="#_4-hands-on-lab-exercises" aria-label="Permalink to &quot;4. Hands-On Lab Exercises&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">LAB 13.1: The Missing Header Error</p><ol><li>Create a recipe that compiles a C program containing <code>#include &lt;zlib.h&gt;</code>.</li><li>Do NOT add <code>DEPENDS = &quot;zlib&quot;</code>.</li><li>Build the recipe. It will fail. Look at the <code>log.do_compile</code> to see the GCC &quot;No such file or directory&quot; error.</li><li>Add <code>DEPENDS = &quot;zlib&quot;</code> and rebuild. It will succeed.</li><li>Navigate to your recipe&#39;s work directory (<code>tmp/work/...</code>) and look inside <code>recipe-sysroot/usr/include/</code>. Verify that <code>zlib.h</code> is actually there!</li></ol></div><div class="tip custom-block"><p class="custom-block-title">LAB 13.2: Exploring the Graph</p><ol><li>Run <code>bitbake -g core-image-minimal</code>.</li><li>Open <code>recipe-depends.dot</code> in a text editor.</li><li>Search for <code>&quot;busybox&quot;</code>. Look at the lines starting with <code>&quot;busybox&quot; -&gt;</code>. These are the dependencies that BusyBox requires to build.</li></ol></div><hr><h2 id="_5-further-reading" tabindex="-1">5. Further Reading <a class="header-anchor" href="#_5-further-reading" aria-label="Permalink to &quot;5. Further Reading&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Resource</th><th>URL</th></tr></thead><tbody><tr><td>Dependencies Documentation</td><td><a href="https://docs.yoctoproject.org/bitbake/bitbake-user-manual/bitbake-user-manual-metadata.html#dependencies" target="_blank" rel="noreferrer">docs.yoctoproject.org/bitbake/bitbake-user-manual/bitbake-user-manual-metadata.html#dependencies</a></td></tr></tbody></table><hr><div style="display:flex;justify-content:space-between;margin-top:2rem;padding-top:1rem;border-top:1px solid #e2e8f0;"><a href="/day12-static-and-dynamic-shared-libraries">← Day 12: Static &amp; Dynamic Libraries</a><a href="/day14-autotools-and-cmake-build-systems">Day 14: Autotools &amp; CMake →</a></div>',43)])])}const b=i(d,[["render",n]]);export{k as __pageData,b as default};
